PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry relu_fp16(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u64 numel
)
{
    // Registers
    .reg .pred   %p<2>;
    .reg .b64    %rd<10>;
    .reg .f16    %f<3>;

    // Load kernel parameters
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u64    %rd3, [numel];

    // -----------------------------------------------------------------
    // Compute linear thread id: idx = blockIdx.x * blockDim.x + threadIdx.x
    // -----------------------------------------------------------------
    mov.u32         %r1, %ctaid.x;          // blockIdx.x
    mov.u32         %r2, %ntid.x;           // blockDim.x
    mov.u32         %r3, %tid.x;            // threadIdx.x
    mad.lo.s32      %r4, %r1, %r2, %r3;     // (blockIdx.x * blockDim.x) + threadIdx.x
    cvt.u64.u32     %rd4, %r4;              // idx as 64‑bit

    // -----------------------------------------------------------------
    // Compute total stride = gridDim.x * blockDim.x
    // -----------------------------------------------------------------
    mov.u32         %r5, %nctaid.x;         // gridDim.x
    mad.lo.s32      %r6, %r5, %r2, 0;       // gridDim.x * blockDim.x
    cvt.u64.u32     %rd5, %r6;              // stride as 64‑bit

    // -----------------------------------------------------------------
    // Loop over elements: while (idx < numel) { ...; idx += stride; }
    // -----------------------------------------------------------------
    .reg .u64 %rdIdx, %rdStride, %rdOffset;
    mov.u64 %rdIdx, %rd4;          // current element index
    mov.u64 %rdStride, %rd5;       // stride in elements

LOOP:
    setp.ge.u64 %p1, %rdIdx, %rd3; // if idx >= numel -> exit
    @%p1 bra DONE;

    // byte offset = idx * sizeof(half) == idx << 1
    shl.b64 %rdOffset, %rdIdx, 1;

    // Load half value
    ld.global.f16 %f1, [%rd1 + %rdOffset];

    // ReLU: max(value, 0)
    mov.f16 %f2, 0f0000;          // zero in fp16
    fmax.f16 %f1, %f1, %f2;

    // Store result
    st.global.f16 [%rd2 + %rdOffset], %f1;

    // idx += stride
    add.u64 %rdIdx, %rdIdx, %rdStride;
    bra LOOP;

DONE:
    ret;
}
'''

