# Python wrapper that loads the PTX and launches the kernel
# --------------------------------------------------------------
import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Allocate output tensor (same shape & dtype)
        y = torch.empty_like(x)

        # Total number of fp16 elements
        n = x.numel()

        # Launch configuration
        block = (256, 1, 1)                         # 256 threads per block
        grid  = ((n + block[0] - 1) // block[0], 1, 1)  # enough blocks for all elements

